#ifndef ARIA2_API_H
#define ARIA2_API_H

#include "common.h"

#include <memory>

#include <aria2/aria2.h>

namespace aria2 {

struct Context;
class ApiCallbackDownloadEventListener;

struct Session {
  Session(const KeyVals& options);
  ~Session();
  std::shared_ptr<Context> context;
  std::unique_ptr<ApiCallbackDownloadEventListener> listener;
};

} // namespace aria2

