69	namespace aria2 {
70	
71	Session::Session(const KeyVals& options)
72	    : context(std::make_shared<Context>(false, 0, nullptr, options))
73	{
74	}
75	
76	Session::~Session() = default;
77	
78	SessionConfig::SessionConfig()
79	    : keepRunning(false),
80	      useSignalHandler(true),
81	      downloadEventCallback(nullptr),
82	      userData(nullptr)
83	{
84	}
85	
86	namespace {
87	Platform* platform = nullptr;
88	} // namespace
89	
90	int libraryInit()
91	{
92	  global::initConsole(true);
93	  try {
94	    platform = new Platform();
95	  }
96	  catch (RecoverableException& e) {
97	    A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, e);
98	    return -1;
99	  }
100	  LogFactory::setConsoleOutput(false);
101	  return 0;
102	}
103	
104	int libraryDeinit()
105	{
106	  delete platform;
107	  return 0;
108	}
109	
110	Session* sessionNew(const KeyVals& options, const SessionConfig& config)
111	{
112	  int rv;
113	  std::unique_ptr<Session> session;
114	  try {
115	    session = make_unique<Session>(options);
116	  }
117	  catch (RecoverableException& e) {
118	    return nullptr;
119	  }
120	  if (session->context->reqinfo) {
121	    if (!config.useSignalHandler) {
122	      session->context->reqinfo->setUseSignalHandler(false);
123	    }
124	    rv = session->context->reqinfo->prepare();
125	    if (rv != 0) {
126	      return nullptr;
127	    }
128	    auto& e = session->context->reqinfo->getDownloadEngine();
129	    if (config.keepRunning) {
130	      e->getRequestGroupMan()->setKeepRunning(true);
131	      // Add command to make aria2 keep event polling
132	      e->addCommand(make_unique<KeepRunningCommand>(e->newCUID(), e.get()));
133	    }
134	    if (config.downloadEventCallback) {
135	      session->listener = make_unique<ApiCallbackDownloadEventListener>(
136	          session.get(), config.downloadEventCallback, config.userData);
137	      SingletonHolder<Notifier>::instance()->addDownloadEventListener(
138	          session->listener.get());
139	    }
140	  }
141	  else {
142	    return nullptr;
143	  }
144	  return session.release();
145	}
146	
147	int sessionFinal(Session* session)
148	{
149	  error_code::Value rv = session->context->reqinfo->getResult();
150	  delete session;
151	  return rv;
152	}
153	
154	int run(Session* session, RUN_MODE mode)
155	{
156	  auto& e = session->context->reqinfo->getDownloadEngine();
157	  return e->run(mode == RUN_ONCE);
158	}
159	
160	int shutdown(Session* session, bool force)
161	{
162	  auto& e = session->context->reqinfo->getDownloadEngine();
163	  if (force) {
164	    e->requestForceHalt();
165	  }
166	  else {
167	    e->requestHalt();
168	  }
169	  // Skip next polling timeout. This avoids 1 second delay when there
170	  // is no Command other than KeepRunningCommand in the queue.
171	  e->setNoWait(true);
172	  return 0;
173	}
