191	template <typename InputIterator, typename Pred>
192	void apiGatherOption(InputIterator first, InputIterator last, Pred pred,
193	                     Option* option,
194	                     const std::shared_ptr<OptionParser>& optionParser)
195	{
196	  for (; first != last; ++first) {
197	    const std::string& optionName = (*first).first;
198	    PrefPtr pref = option::k2p(optionName);
199	    const OptionHandler* handler = optionParser->find(pref);
200	    if (!handler || !pred(handler)) {
201	      // Just ignore the unacceptable options in this context.
202	      continue;
203	    }
204	    handler->parse(*option, (*first).second);
205	  }
206	}
207	} // namespace
