369	int removeDownload(Session* session, A2Gid gid, bool force)
370	{
371	  auto& e = session->context->reqinfo->getDownloadEngine();
372	  std::shared_ptr<RequestGroup> group = e->getRequestGroupMan()->findGroup(gid);
373	  if (group) {
374	    if (group->getState() == RequestGroup::STATE_ACTIVE) {
375	      if (force) {
376	        group->setForceHaltRequested(true, RequestGroup::USER_REQUEST);
377	      }
378	      else {
379	        group->setHaltRequested(true, RequestGroup::USER_REQUEST);
380	      }
381	      e->setRefreshInterval(std::chrono::milliseconds(0));
382	    }
383	    else {
384	      if (group->isDependencyResolved()) {
385	        e->getRequestGroupMan()->removeReservedGroup(gid);
386	      }
387	      else {
388	        return -1;
389	      }
390	    }
391	  }
392	  else {
393	    return -1;
394	  }
395	  return 0;
396	}
