398	int pauseDownload(Session* session, A2Gid gid, bool force)
399	{
400	  auto& e = session->context->reqinfo->getDownloadEngine();
401	  std::shared_ptr<RequestGroup> group = e->getRequestGroupMan()->findGroup(gid);
402	  if (group) {
403	    bool reserved = group->getState() == RequestGroup::STATE_WAITING;
404	    if (pauseRequestGroup(group, reserved, force)) {
405	      e->setRefreshInterval(std::chrono::milliseconds(0));
406	      return 0;
407	    }
408	  }
409	  return -1;
410	}
