412	int unpauseDownload(Session* session, A2Gid gid)
413	{
414	  auto& e = session->context->reqinfo->getDownloadEngine();
415	  std::shared_ptr<RequestGroup> group = e->getRequestGroupMan()->findGroup(gid);
416	  if (!group || group->getState() != RequestGroup::STATE_WAITING ||
417	      !group->isPauseRequested()) {
418	    return -1;
419	  }
420	  else {
421	    group->setPauseRequested(false);
422	    e->getRequestGroupMan()->requestQueueCheck();
423	  }
424	  return 0;
425	}
