235	void MainFrame::OnAddUri(wxCommandEvent& WXUNUSED(event))
236	{
237	  AddUriDialog dlg(this);
238	  int ret = dlg.ShowModal();
239	  if (ret == 0) {
240	    if (dlg.GetUri().IsEmpty()) {
241	      return;
242	    }
243	    std::vector<std::string> uris = {std::string(dlg.GetUri().mb_str())};
244	    std::string optstr(dlg.GetOption().mb_str());
245	    aria2::KeyVals options;
246	    int keyfirst = 0;
247	    for (int i = 0; i < (int)optstr.size(); ++i) {
248	      if (optstr[i] == '\n') {
249	        keyfirst = i + 1;
250	      }
251	      else if (optstr[i] == '=') {
252	        int j;
253	        for (j = i + 1; j < (int)optstr.size(); ++j) {
254	          if (optstr[j] == '\n') {
255	            break;
256	          }
257	        }
258	        if (i - keyfirst > 0) {
259	          options.push_back(
260	              std::make_pair(optstr.substr(keyfirst, i - keyfirst),
261	                             optstr.substr(i + 1, j - i - 1)));
262	        }
263	        keyfirst = j + 1;
264	        i = j;
265	      }
266	    }
267	    jobq_.push(std::unique_ptr<Job>(
268	        new AddUriJob(std::move(uris), std::move(options))));
269	  }
270	}
